package com.muxigame.city;
import java.util.*;
import java.nio.file.*;
import com.mojang.brigadier.arguments.*;
import net.minecraft.commands.Commands;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.*;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.item.ItemStack;
import net.minecraft.network.chat.Component;
import net.minecraft.world.level.storage.LevelResource;
import net.neoforged.neoforge.event.RegisterCommandsEvent;
import net.neoforged.neoforge.network.PacketDistributor;

public final class CityWorksControl {
 static void register(RegisterCommandsEvent e){var root=Commands.literal("cityworks").requires(s->s.hasPermission(2)||s.getEntity() instanceof ServerPlayer p&&p.isCreative());
  root.then(Commands.literal("open").then(Commands.argument("city",StringArgumentType.word()).executes(ctx->{var p=ctx.getSource().getPlayerOrException();snapshot(p,CityData.get(p.server).require(UUID.fromString(StringArgumentType.getString(ctx,"city"))),0,"");return 1;})));
  root.then(Commands.literal("finalize").then(Commands.argument("city",StringArgumentType.word()).executes(ctx->{try{var c=CityData.get(ctx.getSource().getServer()).require(UUID.fromString(StringArgumentType.getString(ctx,"city")));CityWorks.beginFinalize(ctx.getSource().getServer(),c);ctx.getSource().sendSuccess(()->Component.literal("开始首次定稿"),false);return 1;}catch(Exception ex){ctx.getSource().sendFailure(Component.literal(ex.getMessage()));return 0;}})));
  root.then(Commands.literal("report").then(Commands.argument("city",StringArgumentType.word()).executes(ctx->{try{var c=CityData.get(ctx.getSource().getServer()).require(UUID.fromString(StringArgumentType.getString(ctx,"city")));Path file=ctx.getSource().getServer().getWorldPath(LevelResource.ROOT).resolve("city_settlements/maintenance/latest-"+c.id+".json");Files.createDirectories(file.getParent());Files.writeString(file,CityEconomy.JSON.toJson(c.works));ctx.getSource().sendSuccess(()->Component.literal("维护状态已写出："+file),false);return 1;}catch(Exception ex){ctx.getSource().sendFailure(Component.literal(ex.getMessage()));return 0;}})));
  root.then(Commands.literal("lab").executes(ctx->{var p=ctx.getSource().getPlayerOrException();try{UUID id=CityWorksLab.create(p);ctx.getSource().sendSuccess(()->Component.literal("专用验证区："+id+"；等待定稿后 /cityworks labstart "+id),false);return 1;}catch(Exception ex){ctx.getSource().sendFailure(Component.literal(ex.getMessage()));return 0;}}));
  root.then(Commands.literal("labstart").then(Commands.argument("city",StringArgumentType.word()).executes(ctx->{try{var c=CityData.get(ctx.getSource().getServer()).require(UUID.fromString(StringArgumentType.getString(ctx,"city")));CityWorksLab.start(ctx.getSource().getServer(),c);ctx.getSource().sendSuccess(()->Component.literal("原生验收运行中，不重置其他城市"),false);return 1;}catch(Exception ex){ctx.getSource().sendFailure(Component.literal(ex.getMessage()));return 0;}})));
  root.then(Commands.literal("rules").executes(ctx->{try{CityBlockRules.table(ctx.getSource().getServer().getWorldPath(LevelResource.ROOT).resolve("city_settlements/maintenance/block-rules.csv"));ctx.getSource().sendSuccess(()->Component.literal("方块分类表已导出"),false);return 1;}catch(Exception ex){ctx.getSource().sendFailure(Component.literal(ex.getMessage()));return 0;}}));
  root.then(Commands.literal("chestreport").then(Commands.argument("pos",net.minecraft.commands.arguments.coordinates.BlockPosArgument.blockPos()).executes(ctx->{try{var pos=net.minecraft.commands.arguments.coordinates.BlockPosArgument.getBlockPos(ctx,"pos");var l=ctx.getSource().getLevel();var c=RuralTools.city(l,pos);CityEconomy.require(c!=null,"不在城市内");var box=RuralSettlement.get(l.getServer()).state.boxes.get(RuralSettlement.key(c.id,pos.asLong()));CityEconomy.require(box!=null,"不是已登记NPC储藏箱");var report=new LinkedHashMap<String,Object>();report.put("box",box);if(l.hasChunkAt(pos)&&l.getBlockEntity(pos) instanceof RuralBlocks.Link link){report.put("viewers",link.viewers);report.put("materialized",link.inventory!=null);}Path file=l.getServer().getWorldPath(LevelResource.ROOT).resolve("city_settlements/maintenance/chest-"+pos.asLong()+".json");Files.createDirectories(file.getParent());Files.writeString(file,CityEconomy.JSON.toJson(report));ctx.getSource().sendSuccess(()->Component.literal("NPC箱记录已写出："+file),false);return 1;}catch(Exception ex){ctx.getSource().sendFailure(Component.literal(ex.getMessage()));return 0;}})));
  root.then(Commands.literal("labpoststart").then(Commands.argument("city",StringArgumentType.word()).executes(ctx->{try{var c=CityData.get(ctx.getSource().getServer()).require(UUID.fromString(StringArgumentType.getString(ctx,"city")));CityWorksLab.postStart(ctx.getSource().getServer(),c);ctx.getSource().sendSuccess(()->Component.literal("追加审计与接任农夫实际收获验证已启动，不重置库存"),false);return 1;}catch(Exception ex){ctx.getSource().sendFailure(Component.literal(ex.getMessage()));return 0;}})));
  e.getDispatcher().register(root);
 }
 static void request(ServerPlayer p,CityNetwork.Request r){CityData.City c=null;try{RuralTools.editor(p);c=CityData.get(p.server).require(UUID.fromString(r.city()));CityEconomy.require(p.level().dimension().location().toString().equals(c.dimension),"当前维度与城市不同");if(!r.op().equals("works_view"))CityEconomy.require(r.revision()==c.works.revision,"维护设置有变化，请刷新");String message="";
   switch(r.op()){
    case "works_view"->{}
    case "works_finalize"->{CityWorks.beginFinalize(p.server,c);message="开始记录首次定稿；稍后刷新";}
    case "works_pause"->{c.works.enabled=!c.works.enabled;c.works.revision++;message=c.works.enabled?"城市维护恢复":"城市维护暂停";}
    case "works_artisan"->{String[] ids=r.value().split("\\|");RuralSuccession.employ(p.server,c,UUID.fromString(ids[0]),UUID.fromString(ids[1]));c.works.revision++;message="工匠及工坊已关联";}
    case "works_preview"->{String[] args=r.value().split("\\|",-1);CityEconomy.require(args.length==4,"蓝图参数格式错误");var draft=CityArchiveBridge.preview(p,c,args[0],args[1],args[2],args[3].isEmpty()?null:UUID.fromString(args[3]),new BlockPos(r.x(),r.y(),r.z()),r.state(),r.surface());message="投影已生成，确认后下达；实体尚未施工";}
    case "works_build"->{CityArchiveBridge.approve(p,c,UUID.fromString(r.value()));message="蓝图已下达，由工匠逐步施工";}
    case "works_cancel"->{CityArchiveBridge.cancel(c,UUID.fromString(r.value()));message="蓝图已取消，残留标记烂尾";}
    case "works_deposit"->{String[] args=r.value().split("\\|");int n=r.x();CityEconomy.require(n>0&&n<=4096,"存入数量1—4096");var bag=new CityEconomy.Slots(p.getInventory());bag.remove(args[0],n);CityEconomy.require(c.works.resources.size()<256||c.works.resources.containsKey(args[0]),"公共资源种类上限256");CityEconomy.require(c.works.resources.getOrDefault(args[0],0)+n<=1000000,"公共资源数量超限");bag.commit();c.works.resources.merge(args[0],n,Integer::sum);c.works.revision++;message="已从背包实际存入公共资源";}
    case "works_withdraw"->{int n=r.x();CityEconomy.require(n>0&&n<=4096&&c.works.resources.getOrDefault(r.value(),0)>=n,"公共资源不足或数量越界");var bag=new CityEconomy.Slots(p.getInventory());bag.add(r.value(),n);bag.commit();c.works.resources.merge(r.value(),-n,Integer::sum);c.works.revision++;message="已从公共资源实际取出";}
    case "works_prices"->{CityEconomy.require(r.x()>=100&&r.x()<=1000&&r.y()>=1&&r.y()<=10000,"城市基价100—1000%，财富比例1—10000%");c.works.cityPricePercent=r.x();c.works.wealthRatioPercent=r.y();c.works.revision++;message="城乡价格预览参数已保存，未改变正式交易";}
    case "works_rules"->{CityBlockRules.table(p.server.getWorldPath(LevelResource.ROOT).resolve("city_settlements/maintenance/block-rules.csv"));message="已导出全部已安装方块的豁免分类CSV";}
    default->throw new IllegalArgumentException("未知城市维护操作");
   }CityData.get(p.server).setDirty();snapshot(p,c,r.x2(),message);
  }catch(Exception ex){if(c!=null&&CityService.editor(p))snapshot(p,c,r.x2(),"拒绝："+ex.getMessage());else p.sendSystemMessage(Component.literal("[城市维护] "+ex.getMessage()));}}
 static int price(CityWorks.Plan plan,int rural){return (int)Math.max(1,((long)rural*plan.cityPricePercent*plan.wealthRatioPercent+5000)/10000);}
 static void snapshot(ServerPlayer p,CityData.City c,int tab,String message){var t=new CompoundTag();t.putBoolean("Works",true);t.putString("Id",c.id.toString());t.putString("Name",c.name);t.putInt("Tab",tab);t.putLong("Revision",c.works.revision);t.putBoolean("Finalized",c.works.finalized);t.putBoolean("Enabled",c.works.enabled);t.putBoolean("Emergency",c.works.emergency);t.putString("Status",c.works.status);t.putString("Message",message);long hp=c.housing.houses.values().stream().mapToLong(CityWorks::health).sum();t.putLong("Health",hp);t.putLong("Maximum",c.housing.houses.values().stream().mapToLong(h->h.baseline.size()).sum());t.putLong("Wages",c.works.wages);t.putLong("Repaired",c.works.repaired);t.putLong("Demolished",c.works.demolished);t.putLong("Constructed",c.works.constructed);t.putInt("Pending",c.works.pending.size());t.putInt("Illegal",c.works.illegal.size());t.putLong("PublicSilver",CityEconomy.get(p.server).balance(CityWorksFinance.publicPayer(p.server,c)));t.putInt("X",p.blockPosition().getX());t.putInt("Y",p.blockPosition().getY());t.putInt("Z",p.blockPosition().getZ());t.putInt("CityPrice",c.works.cityPricePercent);t.putInt("WealthRatio",c.works.wealthRatioPercent);t.putString("Resources",CityEconomy.JSON.toJson(c.works.resources));var a=new ListTag();for(String f:CityArchiveBridge.files(p))a.add(StringTag.valueOf(f));t.put("Files",a);var draft=CityArchiveBridge.drafts.get(p.getUUID());if(draft!=null&&draft.city().equals(c.id))t.putString("Ticket",draft.ticket().toString());var people=new ListTag();for(UUID id:c.residents.stream().sorted().toList()){var entry=new CompoundTag();entry.putString("Id",id.toString());var person=RuralSettlement.get(p.server).state.people.get(id);var entity=p.serverLevel().getEntity(id);entry.putString("Name",person!=null?person.name:entity==null?id.toString().substring(0,8):entity.getName().getString());people.add(entry);}t.put("People",people);var houses=new ListTag();for(var b:c.buildings.values()){var entry=new CompoundTag();entry.putString("Id",b.id().toString());entry.putString("Name",b.name());entry.putString("Type",b.type());entry.putString("Stage",CityHousing.house(c,b.id()).stage);houses.add(entry);}t.put("Houses",houses);PacketDistributor.sendToPlayer(p,new CityNetwork.Snapshot(t));}
}
